	protected Pharmacy read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Pharmacy" );

		Pharmacy entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Pharmacy with primary key" );
		msg.append( pharmacyId );
		
		PharmacyFetchOneSummary fetchOneSummary = new PharmacyFetchOneSummary( pharmacyId );

		try {
			entity = PharmacyService.getPharmacyInstance().getPharmacy( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Pharmacy " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Pharmacy.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Pharmacy." );

		StringBuilder msg = new StringBuilder( "Failed to update a Pharmacy : " );        
		Pharmacy entity = read();
		UpdatePharmacyCommand command = generateUpdateCommand();
		command.setPharmacyId(entity.getPharmacyId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Pharmacy." );

			// for use later on...
			pharmacyId = entity.getPharmacyId();

			PharmacyService proxy = PharmacyService.getPharmacyInstance();  

			proxy.updatePharmacy( command ).get();

			LOGGER.info( "-- Successfully saved Pharmacy - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + pharmacyId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Pharmacy.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Pharmacy." );

		Pharmacy entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Pharmacy with id " + pharmacyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Pharmacy with id " + pharmacyId );

			throw e;
		}

		try{
			PharmacyService.getPharmacyInstance().delete( new DeletePharmacyCommand( entity.getPharmacyId() ) ).get();
			LOGGER.info( "-- Successfully deleted Pharmacy with id " + pharmacyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Pharmacy with id " + pharmacyId );

			throw e;
		}
	}

	/**
	 * get all Pharmacys.
	 */
	protected List<Pharmacy> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Pharmacys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Pharmacy : " );        
		List<Pharmacy> collection  = new ArrayList<>();

		try {
			// call the static get method on the PharmacyService
			collection = PharmacyService.getPharmacyInstance().getAllPharmacy();
			assertNotNull( collection, "An Empty collection of Pharmacy was incorrectly returned.");
			
			// Now print out the values
			Pharmacy entity = null;            
			Iterator<Pharmacy> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPharmacyId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

